// Whether the current canonical schema has reached the requested target.
type SchemaMigrateResultState string

const (
	SchemaMigrateResultStateConverging SchemaMigrateResultState = "converging"
	SchemaMigrateResultStateReady      SchemaMigrateResultState = "ready"
)

// AllValues returns all SchemaMigrateResultState values.
func (SchemaMigrateResultState) AllValues() []SchemaMigrateResultState {
	return []SchemaMigrateResultState{
		SchemaMigrateResultStateConverging,
		SchemaMigrateResultStateReady,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s SchemaMigrateResultState) MarshalText() ([]byte, error) {
	switch s {
	case SchemaMigrateResultStateConverging:
		return []byte(s), nil
	case SchemaMigrateResultStateReady:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *SchemaMigrateResultState) UnmarshalText(data []byte) error {
	switch SchemaMigrateResultState(data) {
	case SchemaMigrateResultStateConverging:
		*s = SchemaMigrateResultStateConverging
		return nil
	case SchemaMigrateResultStateReady:
		*s = SchemaMigrateResultStateReady
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

